<?php
namespace App\Controllers\Gestion;use App\Core\Controller;use App\Core\Request;use App\Core\Session;use App\Models\Billing;use App\Models\Owner;use App\Models\Patient;use App\Models\Inventory;use App\Models\Catalog;use App\Services\BillingService;use Throwable;
class FacturacionController extends Controller{public function index(Request $r):void{$m=new Billing();$c=new Catalog();$this->view('facturacion/index',['title'=>'Ventas y facturación','sales'=>$m->sales(active_environment_id()),'documents'=>$m->documents(active_environment_id()),'owners'=>(new Owner())->options(active_environment_id()),'patients'=>(new Patient())->allByEnvironment(active_environment_id()),'products'=>(new Inventory())->products(),'services'=>$c->services(),'paymentMethods'=>$c->paymentMethods(),'success'=>Session::pullFlash('success'),'error'=>Session::pullFlash('error')]);}public function store(Request $r):void{$this->go($r,fn()=>(new BillingService())->createSale($r->all(),active_environment_id(),auth_id()),'Venta registrada.');}public function invoice(Request $r,string $id):void{$this->go($r,fn()=>(new BillingService())->queueInvoice((int)$id,active_environment_id(),auth_id()),'Factura encolada para Contífico.');}private function go(Request $r,callable $f,string $ok):void{if(!Session::validateCsrf($r->input('_token'))){http_response_code(419);return;}try{$f();Session::flash('success',$ok);}catch(Throwable $e){Session::flash('error',$e->getMessage());}$this->redirect('/facturacion');}}
